import { type Readable } from 'node:stream';

/** A stored object opened for reading. */
export interface StoredObject {
  stream: Readable;
  /** Size in bytes. */
  size: number;
}

/**
 * Where media bytes live. Keys are opaque, random and generated by the media service;
 * implementations must never derive paths from user input other than a validated key.
 * Local disk today; S3/R2 can be swapped in later behind {@link STORAGE_ADAPTER}.
 */
export interface StorageAdapter {
  put(key: string, data: Buffer, mime: string): Promise<void>;
  /** Throws {@link StorageNotFoundError} when the key does not exist. */
  get(key: string): Promise<StoredObject>;
  /** Idempotent: deleting a missing key is not an error. */
  delete(key: string): Promise<void>;
  exists(key: string): Promise<boolean>;
}

/** Injection token: `@Inject(STORAGE_ADAPTER) private readonly storage: StorageAdapter`. */
export const STORAGE_ADAPTER = Symbol('STORAGE_ADAPTER');

export class StorageNotFoundError extends Error {
  constructor(readonly key: string) {
    super(`Storage object not found: ${key}`);
    this.name = 'StorageNotFoundError';
  }
}
